class CustomHPOStrategy:
    """Adaptive Multi-Fidelity Bayesian Evolution (AMFBE)."""

    def __init__(self, seed: int = 42):
        self.seed = seed
        self.rng = np.random.RandomState(seed)
        # Hyperband parameters
        self.eta = 3.0
        self.min_fidelity = 0.1
        # TPE parameters
        self.gamma = 0.25
        self.n_ei_candidates = 24
        # Evolution parameters
        self.mutation_factor = 0.5
        self.crossover_prob = 0.5
        # Internal state
        self.all_trials = []  # (vec, score, fidelity)
        self.brackets = []
        self.queue = []
        self.initialized = False
        self.budget_spent = 0
        self.total_budget = None

    def _encode(self, config, space):
        vec = []
        for p in space.params:
            val = config[p.name]
            if p.type == "categorical":
                idx = p.choices.index(val)
                vec.append(idx / max(len(p.choices) - 1, 1))
            elif p.type in ("float", "int"):
                if p.log_scale:
                    v = (np.log(val) - np.log(p.low)) / (np.log(p.high) - np.log(p.low))
                else:
                    v = (val - p.low) / (p.high - p.low)
                vec.append(float(np.clip(v, 0, 1)))
        return np.array(vec)

    def _decode(self, vec, space):
        config = {}
        for i, p in enumerate(space.params):
            v = float(np.clip(vec[i], 0, 1))
            if p.type == "categorical":
                idx = int(round(v * max(len(p.choices) - 1, 1)))
                idx = min(idx, len(p.choices) - 1)
                config[p.name] = p.choices[idx]
            elif p.type == "float":
                if p.log_scale:
                    config[p.name] = float(np.exp(
                        np.log(p.low) + v * (np.log(p.high) - np.log(p.low))))
                else:
                    config[p.name] = float(p.low + v * (p.high - p.low))
            elif p.type == "int":
                if p.log_scale:
                    config[p.name] = int(round(np.exp(
                        np.log(p.low) + v * (np.log(p.high) - np.log(p.low)))))
                else:
                    config[p.name] = int(round(p.low + v * (p.high - p.low)))
        return config

    def _sample_from_tpe(self, space):
        if len(self.all_trials) < 10:
            return space.sample_uniform(self.rng)
        vecs = np.array([t[0] for t in self.all_trials])
        scores = np.array([t[1] for t in self.all_trials])
        n_good = max(1, int(self.gamma * len(scores)))
        threshold = np.sort(scores)[-n_good]
        good = vecs[scores >= threshold]
        bad = vecs[scores < threshold]
        if len(bad) == 0:
            bad = good.copy()
        bw_good = max(0.05, good.std() + 1e-6)
        bw_bad = max(0.05, bad.std() + 1e-6)
        best_ei = -np.inf
        best_cfg = None
        for _ in range(self.n_ei_candidates):
            cfg = space.sample_uniform(self.rng)
            x = self._encode(cfg, space)
            log_l = np.log(np.mean(np.exp(-0.5 * np.sum((x - good)**2 / bw_good**2, axis=1))) + 1e-30)
            log_g = np.log(np.mean(np.exp(-0.5 * np.sum((x - bad)**2 / bw_bad**2, axis=1))) + 1e-30)
            ei = log_l - log_g
            if ei > best_ei:
                best_ei = ei
                best_cfg = cfg
        return best_cfg if best_cfg is not None else space.sample_uniform(self.rng)

    def _differential_evolution(self, space, population_vecs):
        n = len(population_vecs)
        if n < 4:
            return space.sample_uniform(self.rng)
        idxs = list(range(n))
        target = self.rng.choice(idxs)
        idxs.remove(target)
        a, b, c = self.rng.choice(idxs, 3, replace=False)
        mutant = population_vecs[a] + self.mutation_factor * (population_vecs[b] - population_vecs[c])
        mutant = np.clip(mutant, 0, 1)
        dim = len(mutant)
        cross_mask = self.rng.rand(dim) < self.crossover_prob
        j_rand = self.rng.randint(dim)
        cross_mask[j_rand] = True
        trial = np.where(cross_mask, mutant, population_vecs[target])
        config = self._decode(trial, space)
        return config

    def _initialize_brackets(self, space, total_budget):
        s_max = max(0, int(np.floor(np.log(total_budget) / np.log(self.eta))))
        s_max = min(s_max, 4)
        for s in range(s_max, -1, -1):
            n = int(np.ceil((s_max + 1) / (s + 1)) * self.eta ** s)
            n = min(n, total_budget)
            r = max(1.0 / self.eta ** s, self.min_fidelity)
            configs = []
            for i in range(n):
                if i < n // 2:
                    configs.append(space.sample_uniform(self.rng))
                else:
                    configs.append(self._sample_from_tpe(space))
            self.brackets.append({
                "configs": configs,
                "fidelity": r,
                "scores": [None] * len(configs),
                "round": 0,
                "s": s,
            })
            for cfg in configs:
                self.queue.append((cfg, r))

    def _advance_bracket(self, bracket, space):
        configs = bracket["configs"]
        scores = bracket["scores"]
        paired = [(s, c) for s, c in zip(scores, configs) if s is not None]
        if not paired:
            return
        paired.sort(key=lambda x: x[0], reverse=True)
        n_keep = max(1, len(paired) // self.eta)
        survivors = paired[:n_keep]
        new_fidelity = min(bracket["fidelity"] * self.eta, 1.0)
        bracket["configs"] = [c for _, c in survivors]
        bracket["scores"] = [None] * len(survivors)
        bracket["fidelity"] = new_fidelity
        bracket["round"] += 1
        for cfg in bracket["configs"]:
            self.queue.append((cfg, new_fidelity))
        if len(survivors) >= 4:
            survivor_vecs = [self._encode(c, space) for _, c in survivors]
            for _ in range(min(2, n_keep)):
                new_cfg = self._differential_evolution(space, survivor_vecs)
                self.queue.append((new_cfg, new_fidelity))

    def suggest(
        self,
        space: SearchSpace,
        history: List[Trial],
        budget_left: int,
    ) -> Tuple[Dict[str, Any], float]:
        # Update internal records
        if len(history) > len(self.all_trials):
            for i in range(len(self.all_trials), len(history)):
                trial = history[i]
                vec = self._encode(trial.config, space)
                self.all_trials.append((vec, trial.score, trial.budget))
                self.budget_spent += trial.budget

        # Initialize brackets on first call
        if not self.initialized:
            self.total_budget = self.budget_spent + budget_left
            self._initialize_brackets(space, self.total_budget)
            self.initialized = True

        # Update bracket scores from latest trial
        if history and self.brackets:
            last_trial = history[-1]
            for bracket in self.brackets:
                for i, cfg in enumerate(bracket["configs"]):
                    if bracket["scores"][i] is None and cfg == last_trial.config:
                        bracket["scores"][i] = last_trial.score
                        if all(s is not None for s in bracket["scores"]):
                            self._advance_bracket(bracket, space)

        # If queue empty, generate via TPE
        if not self.queue:
            config = self._sample_from_tpe(space)
            spent_ratio = self.budget_spent / (self.budget_spent + budget_left)
            if spent_ratio < 0.3:
                fidelity = self.min_fidelity
            elif spent_ratio < 0.6:
                fidelity = 0.33
            else:
                fidelity = 1.0
            if fidelity > budget_left:
                fidelity = max(self.min_fidelity, budget_left * 0.9)
            return config, fidelity

        # Pop from queue
        config, fidelity = self.queue.pop(0)
        if fidelity > budget_left:
            fidelity = max(self.min_fidelity, budget_left * 0.9)
        return config, fidelity
